                "                                                       "
                "expires=Thu, 01-Jan-1970 00:00:01 GMT;\\\n"
                "                                                       "
                'path=/"\n'
                "\n"
                "    }\n"
                "\n"
                "    when HTTP_REQUEST {\n"
