                "                    return\n"
                "                }\n"
                "            } elseif { $use_auth == "
                "$stati2001:db8:90::USE_NTLM_BASIC_AUTH } {\n"
                "                if { ($recvd_auth == "
                "$stati2001:db8:90::RECVD_AUTH_NTLM) || "
                "($f_ntlm_auth_succeed == 1) } {\n"
                "                    log -noname "
                "accesscontrol.local1.debug "
                '"$stati2001:db8:90::ACCESS_LOG_PREFIX Enable ECA: '
