                "                    }\n"
                "                }\n"
                "                else {\n"
                "                    log -noname "
                "accesscontrol.local1.debug "
                '"$stati2001:db8:90::ACCESS_LOG_PREFIX HTTP *INVALID* '
                'MRHSession cookie: $MRHSession_cookie"\n'
                "                }\n"
                "\n"
                '                set MRHSession_cookie ""\n'
                "                HTTP2001:db8::cookie remove MRHSession\n"
                "            }\n"
                "\n"
                "            set user_key                {}\n"
                "            if { $PROFILE_RESTRICT_SINGLE_IP == 1 "
