                "            }\n"
                "            append user_key                 "
                "$password\n"
                "            binary scan [md5 $user_key ] H* "
                "user_key\n"
                "            set user_key                    "
                '"$user.$user_key"\n'
                "\n"
                "            set apm_cookie_list             [ "
                "ACCESS::user getsid $user_key ]\n"
                "            if { [ llength $apm_cookie_list ] != "
                "0 } {\n"
                "                set MRHSession_cookie [ "
                "ACCESS::user getkey [ lindex $apm_cookie_list 0 ] "
                "]\n"
                '                if { $MRHSession_cookie != "" } '
                "{\n"
                "                    HTTP2001:db8::cookie remove "
                "MRHSession \n"
                "                    HTTP2001:db8::cookie insert name "
                "MRHSession value $MRHSession_cookie\n"
                "                    return\n"
                "                }\n"
                "            }\n"
                "\n"
                "            HTTP2001:db8::cookie remove MRHSession\n"
                "            HTTP::header insert "
