from genie.libs.parser.bigip.get_sys_sflow import SysSflow

# ==================================
# Unit test for parsing BigIP URL '/mgmt/tm/sys/sflow'
# ==================================


class FakeResponse_698(object):
    def json(self):
        return {
            "kind": "tm:sys:sflow:sflowcollectionstate",
            "selfLink": "https://localhost/mgmt/tm/sys/sflow?ver=10.225.2.1",
            "items": [
                {
                    "reference": {
                        "link": "https://localhost/mgmt/tm/sys/sflow/global-settings?ver=10.225.2.1"
                    }
                },
                {
                    "reference": {
                        "link": "https://localhost/mgmt/tm/sys/sflow/receiver?ver=10.225.2.1"
                    }
                },
            ],
        }


class test_get_sys_sflow(unittest.TestCase):

    maxDiff = None

    empty_output = {"get.return_value": {}}

    golden_parsed_output = {
        "items": [
            {
                "reference": {
                    "link": "https://localhost/mgmt/tm/sys/sflow/global-settings?ver=10.225.2.1"
                }
            },
            {
                "reference": {
                    "link": "https://localhost/mgmt/tm/sys/sflow/receiver?ver=10.225.2.1"
                }
            },
        ],
        "kind": "tm:sys:sflow:sflowcollectionstate",
        "selfLink": "https://localhost/mgmt/tm/sys/sflow?ver=10.225.2.1",
    }

    golden_output = {"get.return_value": FakeResponse_698()}

    # def test_empty(self):
    #     self.device1 = Mock(**self.empty_output)
    #     obj = SysSflow(device=self.device1, alias='rest', via='rest', context='rest')
    #     with self.assertRaises(SchemaEmptyParserError):
    #         parsed_output = obj.parse()

    def test_golden(self):
        self.device = Mock(**self.golden_output)
        obj = SysSflow(
            device=self.device, alias="rest", via="rest", context="rest"
        )
        parsed_output = obj.parse()
        self.assertEqual(parsed_output, self.golden_parsed_output)





